use canvas_core::{error_archive::{ErrorArchive as A,Limits},error_presentation::Error,remote_error::{RemoteErrorLeaf as L,Severity},payload_codec::Value as V,binary_plist,binary_plist_writer};use std::collections::BTreeMap;
fn main(){let mut main=BTreeMap::from([("errorType".into(),V::String("leaf".into())),("errorTypeDescription".into(),V::String("main".into())),("highValueTitle".into(),V::String("".into())),("options".into(),V::Integer(0)),("severity".into(),V::String("info".into())),("additionalInfo".into(),V::String("a\0b%".into()))]);let a=L::from_dictionary(&main).unwrap();main.insert("errorTypeDescription".into(),V::String("cause".into()));main.insert("highValueTitle".into(),V::String("cause title".into()));main.insert("options".into(),V::Integer(i64::MAX));main.insert("severity".into(),V::String("error".into()));main.insert("additionalInfo".into(),V::String("c\0d%@".into()));let b=L::from_dictionary(&main).unwrap();let tree=A::Wrapper{main:Box::new(A::Leaf(a)),underlying:Box::new(A::Leaf(b))};let p=tree.presentation().unwrap();assert_eq!(p.high_value_title,Some("".into()));assert_eq!(p.options,Some(0));assert_eq!(p.severity,Some(Severity::Info));assert_eq!(p.additional_info,Some("a\0b%: c\0d%@".into()));assert_eq!(p.error_type_description,"[Remote] main.[Remote] cause");assert_eq!(p.additional_diagnostics,None);assert_eq!(tree.presentation_with_limits(Limits::default(),0),Err(Error::ByteLimit));let V::Dictionary(fields)=binary_plist::decode(&binary_plist_writer::encode_dictionary(&tree.to_dictionary().unwrap()).unwrap()).unwrap()else{panic!()};assert_eq!(A::from_dictionary(&fields).unwrap().presentation().unwrap(),p);println!("PASS: WASI wrapper presentation, first-present values, NUL/percent info, bounded output and archive round-trip");}
